DO $$ BEGIN CREATE TYPE public.eligibility_type AS ENUM ('commercial','employer','paid_event','regulated_service','payment_connect'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.eligibility_status AS ENUM ('not_started','pending','approved','rejected','expired','suspended'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.eligibility_decision_source AS ENUM ('manual_review','system_rule','regulatory_check','admin_review','legacy_migration'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.entity_eligibilities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid NOT NULL REFERENCES public.entities(id) ON DELETE CASCADE,eligibility_type public.eligibility_type NOT NULL,status public.eligibility_status NOT NULL DEFAULT 'not_started',decision_source public.eligibility_decision_source NOT NULL,approved_at timestamptz,recheck_at timestamptz,expires_at timestamptz,reviewed_by uuid REFERENCES public.users(id),decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,eligibility_type));
CREATE INDEX IF NOT EXISTS entity_eligibility_status_idx ON public.entity_eligibilities(entity_id,status);ALTER TABLE public.entity_eligibilities ENABLE ROW LEVEL SECURITY;
CREATE POLICY entity_eligibility_owner_read ON public.entity_eligibilities FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.entities e WHERE e.id=entity_id AND e.owner_user_id=auth.uid()) OR public.has_system_role(ARRAY['MODERATOR','SUPER_ADMIN']::public.user_role[]));
GRANT SELECT ON public.entity_eligibilities TO duta_app;
